def drive(me, enemy, arena):
    # Calculate bearing and distance to the enemy
    bearing = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # If we are very close but not moving, we might be riding the enemy's wedge.
    # Back up to reset the engagement and find a better angle.
    if dist < 0.8 and me.speed < 0.3:
        # Back away and turn slightly to avoid going straight back into the wedge
        return (-0.8, -0.6)

    # Turn towards the enemy if the bearing is too wide
    if bearing > 15:
        # Enemy is to the left, turn left
        return (-0.7, 0.7)
    elif bearing < -15:
        # Enemy is to the right, turn right
        return (0.7, -0.7)
    else:
        # Once facing the enemy, avoid a direct head-on collision with the wedge.
        # Use an arcing attack to hit the sides of the opponent.
        if dist < 1.5:
            # Apply asymmetric throttle to create a curved path (arc)
            return (1.0, 0.6)
        else:
            # Charge forward when far away
            return (1.0, 1.0)

