def drive(me, enemy, arena):
    # Initialize arc direction in memory to alternate attack angles
    if "arc_dir" not in me.memory:
        me.memory["arc_dir"] = 1

    # Calculate bearing and distance to the enemy
    bearing = bearing_to(enemy.x, enemy.y)
    dist = distance_to(enemy.x, enemy.y)

    # If we are stuck on the enemy's wedge (low speed, low distance),
    # back away and switch the arc direction to try a different angle.
    if dist < 0.8 and me.speed < 0.3:
        me.memory["arc_dir"] *= -1
        # Back away and turn slightly to reset engagement
        return (-1.0, -0.6)

    # Turn towards the enemy if the bearing is too wide.
    # Bearing positive is to the left, negative to the right.
    if bearing > 20:
        # Turn left: right wheel pushes more than left wheel.
        return (-0.8, 0.8)
    elif bearing < -20:
        # Turn right: left wheel pushes more than right wheel.
        return (0.8, -0.8)
    else:
        # Once facing the enemy, avoid a direct head-on collision with the wedge.
        # Use an arcing attack to hit the sides of the opponent.
        if dist < 1.5:
            # Apply asymmetric throttle to create a curved path.
            if me.memory["arc_dir"] == 1:
                return (1.0, 0.3) # Arc right
            else:
                return (0.3, 1.0) # Arc left
        else:
            # Charge forward when far away to close the distance quickly.
            return (1.0, 1.0)

