def drive(me, enemy, arena):
    # Initialize state in memory
    if "arc_dir" not in me.memory:
        me.memory["arc_dir"] = 1

    # Calculate distance and bearing to enemy
    dist = distance_to(enemy.x, enemy.y)
    bearing = bearing_to(enemy.x, enemy.y)

    # Wall avoidance: steer back toward center if too close to the bubble
    dist_to_center = hypot(me.x, me.y)
    if dist_to_center > 5.8:
        center_bearing = bearing_to(0, 0)
        if center_bearing > 20:
            return (-0.6, 0.6)
        elif center_bearing < -20:
            return (0.6, -0.6)

    # Recovery: if we are stuck against the enemy or on their wedge
    if dist < 0.8 and me.speed < 0.3:
        me.memory["arc_dir"] *= -1
        # Reverse and pivot to break the lock
        return (-1.0, -0.5 if me.memory["arc_dir"] == 1 else -1.0)

    # Steering: Turn toward the enemy
    if bearing > 30:
        # Turn left: right wheel pushes more
        return (-0.8, 0.8)
    elif bearing < -30:
        # Turn right: left wheel pushes more
        return (0.8, -0.8)
    else:
        # Attack Logic: avoid the front wedge by arcing into the flanks
        if dist > 2.5:
            # Charge straight when far
            return (1.0, 1.0)
        elif dist > 1.2:
            # Begin arcing approach
            if me.memory["arc_dir"] == 1:
                return (1.0, 0.4) # Arc right
            else:
                return (0.4, 1.0) # Arc left
        else:
            # Tighten the arc to bypass the wedge and hit the side
            if me.memory["arc_dir"] == 1:
                return (1.0, -0.2)
            else:
                return (-0.2, 1.0)

def weapons(me, enemy, arena):
    # Self-right if the robot is incapacitated
    if me.on_side:
        return [self_right()]

    # Maintain maximum rotor speed for the horizontal ring spinner
    # This is the primary damage dealer and bypasses the front wedge
    target_rpm = me.weapons["front"]["max_rpm"]
    return [spin("front", target_rpm)]
